# Sample only - review before running. Adds an owner to one group.
Connect-MgGraph -Scopes 'Group.ReadWrite.All'
New-MgGroupOwnerByRef -GroupId '<GroupId>' -BodyParameter @{ '@odata.id' = 'https://graph.microsoft.com/v1.0/users/<OwnerObjectId>' }

# Sample only - review before running.
Connect-MgGraph -Scopes 'Policy.ReadWrite.Authorization'
Update-MgPolicyAuthorizationPolicy -DefaultUserRolePermissions @{ AllowedToCreateApps = $false }

# Sample only - review before running.
Connect-MgGraph -Scopes 'Policy.ReadWrite.Authorization'
Update-MgPolicyAuthorizationPolicy -DefaultUserRolePermissions @{ AllowedToCreateTenants = $false }

# Sample only - review before running. Adds an owner to one app registration.
Connect-MgGraph -Scopes 'Application.ReadWrite.All'
New-MgApplicationOwnerByRef -ApplicationId '<ObjectId>' -BodyParameter @{ '@odata.id' = 'https://graph.microsoft.com/v1.0/directoryObjects/<OwnerObjectId>' }

# Sample only - review before running. Adds a 6-month secret; store the returned value securely.
Connect-MgGraph -Scopes 'Application.ReadWrite.All'
Add-MgApplicationPassword -ApplicationId '<ObjectId>' -PasswordCredential @{ DisplayName = 'rotated'; EndDateTime = (Get-Date).AddMonths(6) }

